<?php

/* @autogenerated */
declare(strict_types=1);

use PHPUnit\Framework\TestCase;
use PHPUnit\Framework\Attributes\AllowMockObjectsWithoutExpectations;
use PHPUnit\Framework\MockObject\MockObject;
use Civi\Lughauth\Features\Access\Tenant\Domain\Tenant;
use Civi\Lughauth\Features\Access\Tenant\Domain\Gateway\TenantReadGateway;
use Civi\Lughauth\Features\OAuth\WebAuthn\Domain\WebAuthnChallenge;
use Civi\Lughauth\Features\OAuth\WebAuthn\Domain\WebAuthnCredential;
use Civi\Lughauth\Features\OAuth\WebAuthn\Domain\Gateway\WebAuthnChallengeGateway;
use Civi\Lughauth\Features\OAuth\WebAuthn\Domain\Gateway\WebAuthnCredentialGateway;
use Civi\Lughauth\Features\OAuth\WebAuthn\Domain\Exception\WebAuthnException;
use Civi\Lughauth\Features\OAuth\WebAuthn\Application\Usecase\FinishAuthentication\FinishAuthenticationUsecase;
use Civi\Lughauth\Features\OAuth\WebAuthn\Infrastructure\Service\WebAuthnVerifier;

#[AllowMockObjectsWithoutExpectations]

final class FinishAuthenticationUsecaseUnitTest extends TestCase
{
    private TenantReadGateway&MockObject $tenants;
    private WebAuthnChallengeGateway&MockObject $challengeGateway;
    private WebAuthnCredentialGateway&MockObject $credentialGateway;
    private WebAuthnVerifier&MockObject $verifier;
    private FinishAuthenticationUsecase $usecase;

    protected function setUp(): void
    {
        $this->tenants = $this->createMock(TenantReadGateway::class);
        $this->challengeGateway = $this->createMock(WebAuthnChallengeGateway::class);
        $this->credentialGateway = $this->createMock(WebAuthnCredentialGateway::class);
        $this->verifier = $this->createMock(WebAuthnVerifier::class);

        $this->usecase = new FinishAuthenticationUsecase(
            $this->tenants,
            $this->challengeGateway,
            $this->credentialGateway,
            $this->verifier,
        );
    }

    public function test_valid_assertion_returns_user_info_and_marks_challenge_verified(): void
    {
        $tenant = $this->buildTenant('tenant-uid', 'acme');
        $challenge = $this->buildChallenge(expiresIn: '+5 minutes', verified: false);
        $credential = $this->buildCredential('cred-id', 'user-uid', 'alice@acme.com', signCount: 5);

        $this->tenants->method('findOneByName')->willReturn($tenant);
        $this->challengeGateway->method('findById')->willReturn($challenge);
        $this->credentialGateway->method('findByCredentialId')->willReturn($credential);
        $this->verifier->method('verifyAssertion')->willReturn(6);

        $this->credentialGateway->expects($this->once())->method('updateSignCount')
            ->with('cred-id', 'tenant-uid', 6, $this->anything());
        $this->challengeGateway->expects($this->once())->method('markVerified');

        $result = $this->usecase->finish(
            'challenge-id',
            'acme',
            ['id' => 'cred-id', 'response' => []],
            'https://acme.example.com',
            'acme.example.com',
        );

        $this->assertSame('user-uid', $result['userUid']);
        $this->assertSame('alice@acme.com', $result['username']);
    }

    public function test_throws_when_challenge_not_found(): void
    {
        $this->tenants->method('findOneByName')->willReturn($this->buildTenant('tid', 'acme'));
        $this->challengeGateway->method('findById')->willReturn(null);

        $this->expectException(WebAuthnException::class);
        $this->usecase->finish('bad-id', 'acme', ['id' => 'c'], 'https://x.com', 'x.com');
    }

    public function test_throws_when_challenge_expired(): void
    {
        $this->tenants->method('findOneByName')->willReturn($this->buildTenant('tid', 'acme'));
        $challenge = $this->buildChallenge(expiresIn: '-1 minute', verified: false);
        $this->challengeGateway->method('findById')->willReturn($challenge);

        $this->expectException(WebAuthnException::class);
        $this->usecase->finish('cid', 'acme', ['id' => 'c'], 'https://x.com', 'x.com');
    }

    public function test_throws_when_credential_not_found(): void
    {
        $this->tenants->method('findOneByName')->willReturn($this->buildTenant('tid', 'acme'));
        $this->challengeGateway->method('findById')->willReturn($this->buildChallenge('+5 minutes', false));
        $this->credentialGateway->method('findByCredentialId')->willReturn(null);

        $this->expectException(WebAuthnException::class);
        $this->usecase->finish('cid', 'acme', ['id' => 'no-cred'], 'https://x.com', 'x.com');
    }

    public function test_throws_when_credential_disabled(): void
    {
        $this->tenants->method('findOneByName')->willReturn($this->buildTenant('tid', 'acme'));
        $this->challengeGateway->method('findById')->willReturn($this->buildChallenge('+5 minutes', false));
        $this->credentialGateway->method('findByCredentialId')
            ->willReturn($this->buildCredential('c', 'u', 'u@x.com', signCount: 0, enabled: false));

        $this->expectException(WebAuthnException::class);
        $this->usecase->finish('cid', 'acme', ['id' => 'c'], 'https://x.com', 'x.com');
    }

    public function test_sign_count_is_updated_after_valid_assertion(): void
    {
        $this->tenants->method('findOneByName')->willReturn($this->buildTenant('tid', 'acme'));
        $this->challengeGateway->method('findById')->willReturn($this->buildChallenge('+5 minutes', false));
        $this->credentialGateway->method('findByCredentialId')
            ->willReturn($this->buildCredential('c', 'u', 'u@x.com', signCount: 10));
        $this->verifier->method('verifyAssertion')->willReturn(11);

        $this->credentialGateway->expects($this->once())->method('updateSignCount')
            ->with('c', 'tid', 11, $this->anything());
        $this->challengeGateway->method('markVerified');

        $this->usecase->finish('cid', 'acme', ['id' => 'c', 'response' => []], 'https://x.com', 'x.com');
    }

    private function buildTenant(string $uid, string $name): Tenant&MockObject
    {
        $tenant = $this->createMock(Tenant::class);
        $tenant->method('uid')->willReturn($uid);
        $tenant->method('getName')->willReturn($name);
        return $tenant;
    }

    private function buildChallenge(string $expiresIn, bool $verified): WebAuthnChallenge
    {
        return new WebAuthnChallenge(
            challengeId: 'challenge-id',
            tenantId: 'tenant-uid',
            userUid: null,
            challenge: 'abc123',
            type: 'authenticate',
            optionsJson: null,
            createdAt: new DateTimeImmutable(),
            expiresAt: new DateTimeImmutable($expiresIn),
            verified: $verified,
            verifiedAt: null,
            verifiedUserUid: null,
            verifiedUsername: null,
        );
    }

    private function buildCredential(
        string $credentialId,
        string $userUid,
        string $username,
        int $signCount,
        bool $enabled = true,
    ): WebAuthnCredential {
        return new WebAuthnCredential(
            uid: 'cred-row-uid',
            tenantId: 'tenant-uid',
            userUid: $userUid,
            username: $username,
            credentialId: $credentialId,
            publicKey: '-----BEGIN PUBLIC KEY-----',
            signCount: $signCount,
            aaguid: null,
            deviceName: null,
            transports: null,
            createdAt: new DateTimeImmutable(),
            lastUsedAt: null,
            enabled: $enabled,
        );
    }
}
